const LONG = {
k1:{h:["Ensimmäinen päivä Suomessa","My first day in Finland","फिनल्यान्डमा मेरो पहिलो दिन"], pre:["Ram tells about his first school day. Look for olla: olen, on, olemme, ovat.","राम आफ्नो पहिलो दिनबारे बताउँछन्। olla का रूप खोज्नुहोस्।"],
paras:[
[["Hei! Minä olen Ram.","Hi! I am Ram.","नमस्ते! म राम हुँ।"],["Olen nepalilainen opiskelija.","I am a Nepali student.","म नेपाली विद्यार्थी हुँ।"],["Nyt olen Suomessa, Espoossa.","Now I am in Finland, in Espoo.","अहिले म फिनल्यान्डको एस्पोमा छु।"],["On maanantai, ja kello on kahdeksan.","It is Monday, and it is eight o'clock.","सोमबार हो, र आठ बजेको छ।"],["Tänään on ensimmäinen koulupäivä.","Today is the first school day.","आज विद्यालयको पहिलो दिन हो।"]],
[["Ovella on naapuri. Hän on vanha nainen, Aino.","There is a neighbour at the door. She is an old woman, Aino.","ढोकामा छिमेकी छिन्। उनी बूढी महिला आइनो हुन्।"],["– Huomenta! Mitä kuuluu? hän kysyy.","\"Good morning! How are you?\" she asks.","\"शुभ प्रभात! कस्तो छ?\" उनी सोध्छिन्।"],["– Huomenta! Kiitos, hyvää, minä vastaan.","\"Morning! Fine, thanks,\" I answer.","\"शुभ प्रभात! ठीक छ, धन्यवाद,\" म जवाफ दिन्छु।"],["– Oletko uusi naapuri?","\"Are you the new neighbour?\"","\"के तिमी नयाँ छिमेकी हौ?\""],["– Olen. Minä olen Ram. Hauska tutustua!","\"Yes. I am Ram. Nice to meet you!\"","\"हो। म राम हुँ। भेटेर खुसी लाग्यो!\""],["– Hauska tutustua! Tervetuloa!","\"Nice to meet you! Welcome!\"","\"भेटेर खुसी लाग्यो! स्वागत छ!\""]],
[["Bussi on pysäkillä. Se on numero kaksikymmentä.","The bus is at the stop. It is number twenty.","बस बिसौनीमा छ। त्यो नम्बर बीस हो।"],["Kuljettaja on mies. Hän on ystävällinen.","The driver is a man. He is friendly.","चालक पुरुष हुन्। उनी मिलनसार छन्।"],["– Päivää! – Päivää!","\"Good day!\" – \"Good day!\"","\"नमस्ते!\" – \"नमस्ते!\""],["Bussi on täynnä, mutta ihmiset ovat hiljaa.","The bus is full, but the people are quiet.","बस भरिएको छ, तर मानिसहरू चुपचाप छन्।"],["Suomalaiset ovat usein hiljaa bussissa.","Finns are often quiet on the bus.","फिनिसहरू प्रायः बसमा चुपचाप हुन्छन्।"]],
[["Yliopisto on iso. Luokka on numero 204.","The university is big. The classroom is number 204.","विश्वविद्यालय ठूलो छ। कक्षाकोठा नम्बर २०४ हो।"],["Luokassa on kaksitoista opiskelijaa.","There are twelve students in the classroom.","कक्षामा बाह्र जना विद्यार्थी छन्।"],["Opettaja on Mari. Hän on suomalainen.","The teacher is Mari. She is Finnish.","शिक्षक मारी हुन्। उनी फिनिस हुन्।"],["– Hei kaikki! Minä olen Mari. Kuka sinä olet?","\"Hi everyone! I am Mari. Who are you?\"","\"नमस्ते सबैलाई! म मारी हुँ। तिमी को हौ?\""],["– Minä olen Ram. Olen Nepalista.","\"I am Ram. I am from Nepal.\"","\"म राम हुँ। म नेपालबाट हुँ।\""],["Luokassa on myös Mei. Hän on Kiinasta.","Mei is also in the class. She is from China.","कक्षामा मेई पनि छिन्। उनी चीनबाट हुन्।"],["Anna on Virosta, ja Omar on Somaliasta.","Anna is from Estonia, and Omar is from Somalia.","आन्ना इस्टोनियाबाट र ओमार सोमालियाबाट हुन्।"],["Me olemme kaikki uusia Suomessa.","We are all new in Finland.","हामी सबै फिनल्यान्डमा नयाँ छौं।"]],
[["Tauolla me olemme kahvilassa.","At the break we are in the café.","विश्रामको समयमा हामी क्याफेमा छौं।"],["Mei on ystävällinen ja iloinen.","Mei is kind and cheerful.","मेई दयालु र हँसिली छिन्।"],["– Mikä sinun puhelinnumerosi on? Mei kysyy.","\"What is your phone number?\" Mei asks.","\"तिम्रो फोन नम्बर के हो?\" मेई सोध्छिन्।"],["– Se on nolla neljä nolla, yksi kaksi kolme, neljä viisi kuusi seitsemän.","\"It is 040 123 4567.\"","\"त्यो ०४० १२३ ४५६७ हो।\""],["– Kiitos! Nähdään huomenna!","\"Thanks! See you tomorrow!\"","\"धन्यवाद! भोलि भेटौँला!\""]],
[["Illalla olen taas kotona.","In the evening I am at home again.","बेलुका म फेरि घरमा छु।"],["Olen väsynyt, mutta onnellinen.","I am tired, but happy.","म थाकेको छु, तर खुसी छु।"],["Suomi on kylmä, mutta ihmiset ovat ystävällisiä.","Finland is cold, but the people are kind.","फिनल्यान्ड चिसो छ, तर मानिसहरू दयालु छन्।"],["Hyvää yötä, Suomi!","Good night, Finland!","शुभ रात्रि, फिनल्यान्ड!"]]],
q:[["mc","Mikä päivä on?","What day is it?",["maanantai","perjantai","sunnuntai"],0],["mc","Kuka Aino on?","Who is Aino?",["opettaja","naapuri","opiskelija"],1],["mc","Mikä numero bussi on?","Which number is the bus?",["12","20","204"],1],["tf","Bussissa ihmiset puhuvat paljon.","People talk a lot on the bus.",false],["mc","Montako opiskelijaa luokassa on?","How many students are in the class?",["10","12","20"],1],["mc","Mistä Omar on?","Where is Omar from?",["Virosta","Kiinasta","Somaliasta"],2],["tf","Mari on suomalainen opettaja.","Mari is a Finnish teacher.",true],["tf","Illalla Ram on surullinen.","In the evening Ram is sad.",false]],
open:[["Kuka sinä olet?","Minä olen Ram. Olen opiskelija."],["Mistä sinä olet?","Olen Nepalista."],["Millainen Ramin päivä on?","Se on pitkä, mutta hyvä. Ram on väsynyt, mutta onnellinen."]]},

k2:{h:["Kielikahvilassa","At the language café","भाषा क्याफेमा"], pre:["Ram and Sita meet Mikko. Look for verb endings (-n, -t, -mme, -tte, -vat) and en, et, ei.","राम र सीताले मिक्कोलाई भेट्छन्। क्रियाका अन्त्य खोज्नुहोस्।"],
paras:[
[["Joka torstai yliopistolla on kielikahvila.","Every Thursday there is a language café at the university.","हरेक बिहीबार विश्वविद्यालयमा भाषा क्याफे हुन्छ।"],["Kielikahvilassa ihmiset puhuvat suomea.","In the language café people speak Finnish.","भाषा क्याफेमा मानिसहरू फिनिस बोल्छन्।"],["Ram ja Sita istuvat pöydässä.","Ram and Sita sit at a table.","राम र सीता टेबलमा बस्छन्।"],["He ovat Nepalista, mutta he eivät puhu nepalia kahvilassa.","They are from Nepal, but they don't speak Nepali in the café.","उनीहरू नेपालबाट हुन्, तर क्याफेमा नेपाली बोल्दैनन्।"],["– Täällä me puhumme vain suomea! Sita sanoo.","\"Here we speak only Finnish!\" Sita says.","\"यहाँ हामी फिनिस मात्र बोल्छौं!\" सीता भन्छिन्।"]],
[["Pöytään tulee mies.","A man comes to the table.","टेबलमा एक जना मान्छे आउँछन्।"],["– Hei! Onko tämä paikka vapaa?","\"Hi! Is this seat free?\"","\"नमस्ते! यो सिट खाली छ?\""],["– On. Istu, ole hyvä!","\"It is. Sit down, please!\"","\"छ। बस्नुहोस्!\""],["– Kiitos. Minä olen Mikko. Olen suomalainen.","\"Thanks. I am Mikko. I am Finnish.\"","\"धन्यवाद। म मिक्को हुँ। म फिनिस हुँ।\""],["– Hauska tutustua! Me olemme Ram ja Sita.","\"Nice to meet you! We are Ram and Sita.\"","\"भेटेर खुसी लाग्यो! हामी राम र सीता हौं।\""]],
[["– Mistä te olette kotoisin? Mikko kysyy.","\"Where are you from?\" Mikko asks.","\"तपाईंहरू कहाँबाट हुनुहुन्छ?\" मिक्को सोध्छन्।"],["– Olemme kotoisin Nepalista. Minä olen Pokharasta, ja Sita on Kathmandusta.","\"We are from Nepal. I am from Pokhara, and Sita is from Kathmandu.\"","\"हामी नेपालबाट हौं। म पोखराबाट, सीता काठमाडौंबाट।\""],["– Mitä kieliä te puhutte?","\"What languages do you speak?\"","\"तपाईंहरू कुन-कुन भाषा बोल्नुहुन्छ?\""],["– Puhumme nepalia, englantia ja hindiä. Ja vähän suomea!","\"We speak Nepali, English and Hindi. And a little Finnish!\"","\"हामी नेपाली, अंग्रेजी र हिन्दी बोल्छौं। अनि अलिअलि फिनिस!\""],["– Te puhutte jo hyvin suomea!","\"You already speak Finnish well!\"","\"तपाईंहरू पहिले नै राम्रो फिनिस बोल्नुहुन्छ!\""],["– Kiitos! Mutta emme ymmärrä kaikkea.","\"Thanks! But we don't understand everything.\"","\"धन्यवाद! तर हामी सबै बुझ्दैनौं।\""]],
[["Mikko puhuu suomea ja ruotsia.","Mikko speaks Finnish and Swedish.","मिक्को फिनिस र स्विडिस बोल्छन्।"],["Hän ei puhu nepalia, mutta hän osaa sanoa namaste.","He doesn't speak Nepali, but he can say namaste.","उनी नेपाली बोल्दैनन्, तर 'नमस्ते' भन्न जान्छन्।"],["Hän opiskelee yliopistossa tietotekniikkaa.","He studies computer science at the university.","उनी विश्वविद्यालयमा कम्प्युटर विज्ञान पढ्छन्।"],["Hän asuu Helsingissä, mutta hänen perheensä asuu Turussa.","He lives in Helsinki, but his family lives in Turku.","उनी हेल्सिंकीमा बस्छन्, तर उनको परिवार टुर्कुमा बस्छ।"]],
[["– Haluatteko kahvia? Mikko kysyy.","\"Would you like coffee?\" Mikko asks.","\"कफी खानुहुन्छ?\" मिक्को सोध्छन्।"],["– Minä otan teetä, Ram sanoo.","\"I'll have tea,\" Ram says.","\"म चिया लिन्छु,\" राम भन्छन्।"],["– Minä en juo kahvia. Otan mehua, Sita sanoo.","\"I don't drink coffee. I'll have juice,\" Sita says.","\"म कफी पिउँदिनँ। जुस लिन्छु,\" सीता भन्छिन्।"],["Mikko ostaa kaksi teetä ja yhden mehun.","Mikko buys two teas and one juice.","मिक्को दुई कप चिया र एउटा जुस किन्छन्।"],["Tee maksaa kaksi euroa, ja mehu maksaa kaksi euroa viisikymmentä.","Tea costs two euros, and juice costs two euros fifty.","चिया दुई युरो र जुस दुई युरो पचास पर्छ।"],["Yhteensä se maksaa kuusi euroa viisikymmentä.","In total it costs six euros fifty.","जम्मा छ युरो पचास पर्छ।"],["– Kiitos, Mikko! Ensi kerralla me maksamme!","\"Thanks, Mikko! Next time we'll pay!\"","\"धन्यवाद, मिक्को! अर्को पटक हामी तिर्छौं!\""]],
[["Kello on kuusi, ja kielikahvila loppuu.","It is six o'clock, and the language café ends.","छ बज्यो, र भाषा क्याफे सकिन्छ।"],["– Tuletteko ensi torstaina? Mikko kysyy.","\"Are you coming next Thursday?\" Mikko asks.","\"अर्को बिहीबार आउनुहुन्छ?\" मिक्को सोध्छन्।"],["– Tulemme! Nähdään!","\"We are! See you!\"","\"आउँछौं! भेटौँला!\""],["Ram on iloinen. Hän oppii joka viikko uusia sanoja.","Ram is happy. He learns new words every week.","राम खुसी छन्। उनी हरेक हप्ता नयाँ शब्द सिक्छन्।"]]],
q:[["mc","Milloin kielikahvila on?","When is the language café?",["maanantaina","torstaina","lauantaina"],1],["tf","Kahvilassa Ram ja Sita puhuvat nepalia.","In the café Ram and Sita speak Nepali.",false],["mc","Mistä Sita on kotoisin?","Where is Sita from?",["Pokharasta","Kathmandusta","Turusta"],1],["mc","Mitä kieliä Mikko puhuu?","What languages does Mikko speak?",["suomea ja ruotsia","suomea ja nepalia","englantia ja hindiä"],0],["mc","Missä Mikon perhe asuu?","Where does Mikko's family live?",["Helsingissä","Espoossa","Turussa"],2],["mc","Mitä Sita juo?","What does Sita drink?",["kahvia","teetä","mehua"],2],["mc","Paljonko juomat maksavat yhteensä?","How much do the drinks cost in total?",["4,50 €","6,50 €","2,50 €"],1],["tf","Ram ja Sita tulevat ensi torstaina.","Ram and Sita are coming next Thursday.",true]],
open:[["Mistä sinä olet kotoisin?","Olen kotoisin Nepalista, Pokharasta."],["Mitä kieliä sinä puhut?","Puhun nepalia, englantia ja vähän suomea."],["Mitä sinä juot kahvilassa?","Juon teetä. En juo kahvia."]]},

k3:{h:["Sähköposti Mikolle","An email to Mikko","मिक्कोलाई इमेल"], pre:["Ram writes about the weather and buying a winter coat. Look for genitives (minun, Mein, syksyn) and colour words.","राम मौसम र जाडो ज्याकेटबारे लेख्छन्। -n (को) र रङका शब्द खोज्नुहोस्।"],
paras:[
[["Aihe: Terveisiä Espoosta!","Subject: Greetings from Espoo!","विषय: एस्पोबाट शुभकामना!"],["Hei Mikko!","Hi Mikko!","नमस्ते मिक्को!"],["Kiitos viestistä! Mitä sinulle kuuluu? Minulle kuuluu hyvää.","Thanks for the message! How are you? I am fine.","सन्देशका लागि धन्यवाद! तिमीलाई कस्तो छ? मलाई ठीक छ।"]],
[["On marraskuu, ja Suomessa on nyt syksy.","It is November, and it is autumn in Finland now.","नोभेम्बर हो, र अहिले फिनल्यान्डमा शरद ऋतु छ।"],["Sää on kylmä ja pilvinen. Usein sataa vettä.","The weather is cold and cloudy. It often rains.","मौसम चिसो र बादल लागेको छ। प्रायः पानी पर्छ।"],["Aamulla on pimeää, ja illalla on pimeää. Päivä on lyhyt.","It is dark in the morning and dark in the evening. The day is short.","बिहान अँध्यारो, बेलुका पनि अँध्यारो। दिन छोटो छ।"],["Lämpötila on vain plus kolme astetta.","The temperature is only plus three degrees.","तापक्रम केवल तीन डिग्री छ।"],["Äiti sanoo, että Kathmandussa on nyt kaksikymmentä astetta lämmintä.","Mother says it is twenty degrees warm in Kathmandu now.","आमा भन्नुहुन्छ, अहिले काठमाडौंमा बीस डिग्री न्यानो छ।"]],
[["Minun takkini on liian ohut.","My coat is too thin.","मेरो ज्याकेट धेरै पातलो छ।"],["Huomenna menen kauppaan ja ostan uuden talvitakin.","Tomorrow I'll go to the shop and buy a new winter coat.","भोलि म पसल गएर नयाँ जाडो ज्याकेट किन्छु।"],["Haluan sinisen tai mustan takin.","I want a blue or a black coat.","मलाई निलो वा कालो ज्याकेट चाहिन्छ।"],["Tarvitsen myös pipon, hanskat ja villasukat.","I also need a beanie, gloves and wool socks.","मलाई टोपी, पन्जा र ऊनी मोजा पनि चाहिन्छ।"]],
[["Syksyn värit ovat kauniita.","The colours of autumn are beautiful.","शरदका रङ सुन्दर छन्।"],["Puut ovat keltaisia, punaisia ja oransseja.","The trees are yellow, red and orange.","रूखहरू पहेँलो, रातो र सुन्तले छन्।"],["Puiston järvi on harmaa ja hiljainen.","The park's lake is grey and quiet.","पार्कको ताल खैरो र शान्त छ।"],["Meidän opettajamme Mari sanoo, että joulukuussa tulee lunta.","Our teacher Mari says that snow comes in December.","हाम्रो शिक्षक मारी भन्नुहुन्छ, डिसेम्बरमा हिउँ पर्छ।"],["Odotan lunta! Pokharassa ei ole lunta, mutta vuorilla on.","I am waiting for snow! There is no snow in Pokhara, but there is on the mountains.","म हिउँको प्रतीक्षामा छु! पोखरामा हिउँ हुँदैन, तर हिमालमा हुन्छ।"]],
[["Milloin sinä tulet Espooseen? Onko Turussa nyt kylmä?","When are you coming to Espoo? Is it cold in Turku now?","तिमी एस्पो कहिले आउँछौ? टुर्कुमा अहिले चिसो छ?"],["Voitko auttaa minua? Missä kaupassa on hyviä talvikenkiä?","Can you help me? Which shop has good winter shoes?","मलाई सहयोग गर्छौ? कुन पसलमा राम्रा जाडो जुत्ता छन्?"],["Kirjoita pian!","Write soon!","छिट्टै लेख!"],["Terveisin, Ram","Best regards, Ram","शुभकामनासहित, राम"],["P.S. Mein syntymäpäivä on lauantaina. Tuletko juhliin?","P.S. Mei's birthday is on Saturday. Are you coming to the party?","पुनश्च: मेईको जन्मदिन शनिबार छ। भोजमा आउँछौ?"]],
[["Vastaus: Moi Ram!","Reply: Hi Ram!","जवाफ: नमस्ते राम!"],["Kiitos viestistä! Turussa on myös kylmä ja tuulinen.","Thanks for the message! It is also cold and windy in Turku.","सन्देशका लागि धन्यवाद! टुर्कुमा पनि चिसो र हावा चलेको छ।"],["Hyvä talvitakki on lämmin ja pitkä. Musta on hyvä väri.","A good winter coat is warm and long. Black is a good colour.","राम्रो जाडो ज्याकेट न्यानो र लामो हुन्छ। कालो राम्रो रङ हो।"],["Kauppakeskuksen kenkäkaupassa on hyviä talvikenkiä.","The shoe shop in the shopping centre has good winter shoes.","सपिङ सेन्टरको जुत्ता पसलमा राम्रा जाडो जुत्ता छन्।"],["Tulen Espooseen lauantaina, ja tulen Mein juhliin!","I'm coming to Espoo on Saturday, and I'm coming to Mei's party!","म शनिबार एस्पो आउँछु, र मेईको भोजमा पनि आउँछु!"],["Nähdään! Mikko","See you! Mikko","भेटौँला! मिक्को"]]],
q:[["mc","Mikä kuukausi on?","Which month is it?",["lokakuu","marraskuu","joulukuu"],1],["mc","Millainen sää Espoossa on?","What is the weather like in Espoo?",["kylmä ja pilvinen","lämmin ja aurinkoinen","kuuma"],0],["mc","Paljonko lämpötila on?","What is the temperature?",["+3","+20","−3"],0],["tf","Ramin takki on lämmin.","Ram's coat is warm.",false],["mc","Minkä värisen takin Ram haluaa?","What colour coat does Ram want?",["punaisen","sinisen tai mustan","keltaisen"],1],["mc","Milloin tulee lunta?","When does snow come?",["marraskuussa","joulukuussa","tammikuussa"],1],["tf","Pokharassa on paljon lunta.","There is a lot of snow in Pokhara.",false],["mc","Kenen syntymäpäivä on lauantaina?","Whose birthday is on Saturday?",["Ramin","Mikon","Mein"],2]],
open:[["Millainen sää tänään on?","Tänään on kylmä ja pilvinen. Lämpötila on plus kolme astetta."],["Minkä värinen sinun takkisi on?","Minun takkini on musta."],["Millainen sää Nepalissa on nyt?","Nepalissa on nyt lämmin ja aurinkoinen sää."]]},

k4:{h:["Valokuva-albumi","The photo album","फोटो एल्बम"], pre:["Ram shows Mei his family photos. Look for minulla on, hänellä on and ei ole + partitive.","राम मेईलाई परिवारका फोटो देखाउँछन्। minulla on र ei ole खोज्नुहोस्।"],
paras:[
[["Sunnuntaina Mei on Ramin luona.","On Sunday Mei is at Ram's place.","आइतबार मेई रामको घरमा छिन्।"],["Ramilla on vanha valokuva-albumi.","Ram has an old photo album.","रामसँग पुरानो फोटो एल्बम छ।"],["– Kuka tämä on? Mei kysyy.","\"Who is this?\" Mei asks.","\"यो को हो?\" मेई सोध्छिन्।"],["– Se on minun äitini. Hänen nimensä on Gita.","\"That's my mother. Her name is Gita.\"","\"उहाँ मेरी आमा। उहाँको नाम गीता हो।\""]],
[["– Äiti on viisikymmentäkaksi vuotta vanha.","\"Mother is fifty-two years old.\"","\"आमा बाउन्न वर्षकी हुनुहुन्छ।\""],["– Hänellä on pitkä musta tukka ja ruskeat silmät.","\"She has long black hair and brown eyes.\"","\"उहाँको लामो कालो कपाल र खैरा आँखा छन्।\""],["– Hän on opettaja. Hän on ahkera ja kärsivällinen.","\"She is a teacher. She is hard-working and patient.\"","\"उहाँ शिक्षक हुनुहुन्छ। उहाँ मेहनती र धैर्यवान हुनुहुन्छ।\""]],
[["– Entä tämä mies? Onko hän sinun isäsi?","\"And this man? Is he your father?\"","\"अनि यो मान्छे? उहाँ तिम्रो बुबा हो?\""],["– On. Isällä on parta ja silmälasit. Hän on lääkäri.","\"Yes. Father has a beard and glasses. He is a doctor.\"","\"हो। बुबाको दाह्री र चस्मा छ। उहाँ डाक्टर हुनुहुन्छ।\""],["– Isä on vähän ujo, mutta hän on tosi hauska.","\"Father is a bit shy, but he is really funny.\"","\"बुबा अलि लजालु हुनुहुन्छ, तर धेरै रमाइलो हुनुहुन्छ।\""]],
[["– Onko sinulla sisaruksia?","\"Do you have brothers and sisters?\"","\"तिम्रा दाजुभाइ-दिदीबहिनी छन्?\""],["– On. Minulla on yksi sisko ja kaksi veljeä.","\"Yes. I have one sister and two brothers.\"","\"छन्। मेरी एउटी बहिनी र दुई भाइ छन्।\""],["– Sisko Asha on kaksikymmentä. Hän opiskelee Kathmandussa.","\"My sister Asha is twenty. She studies in Kathmandu.\"","\"बहिनी आशा बीस वर्षकी हुन्। उनी काठमाडौंमा पढ्छिन्।\""],["– Hänellä on lyhyt kihara tukka. Hän on puhelias ja sosiaalinen.","\"She has short curly hair. She is talkative and sociable.\"","\"उनको छोटो घुम्रिएको कपाल छ। उनी बोलक्कड र मिलनसार छिन्।\""],["– Veljet ovat kaksoset! He ovat viisitoista.","\"My brothers are twins! They are fifteen.\"","\"भाइहरू जुम्ल्याहा हुन्! उनीहरू पन्ध्र वर्षका छन्।\""]],
[["– Minulla ei ole veljeä eikä siskoa, Mei sanoo.","\"I don't have a brother or a sister,\" Mei says.","\"मेरो दाजुभाइ वा दिदीबहिनी छैनन्,\" मेई भन्छिन्।"],["– Olen ainoa lapsi. Mutta minulla on kissa! Sen nimi on Lumi.","\"I am an only child. But I have a cat! Its name is Lumi.\"","\"म एक्लो सन्तान हुँ। तर मेरो बिरालो छ! त्यसको नाम लुमी हो।\""],["– Onko sinulla lemmikkiä?","\"Do you have a pet?\"","\"तिम्रो घरपालुवा जनावर छ?\""],["– Ei ole. Meillä on Nepalissa koira, mutta täällä minulla ei ole lemmikkiä.","\"No. We have a dog in Nepal, but here I don't have a pet.\"","\"छैन। नेपालमा हाम्रो कुकुर छ, तर यहाँ मसँग घरपालुवा छैन।\""]],
[["– Onko sinulla ikävä perhettä?","\"Do you miss your family?\"","\"तिमीलाई परिवारको याद आउँछ?\""],["– On. Soitan äidille joka sunnuntai. Meillä on videopuhelu.","\"Yes. I call my mother every Sunday. We have a video call.\"","\"आउँछ। म हरेक आइतबार आमालाई फोन गर्छु। हामी भिडियो कल गर्छौं।\""],["– Mummo on myös kuvassa. Hän on kahdeksankymmentä, mutta hän on terve ja reipas.","\"Grandma is also in the picture. She is eighty, but she is healthy and lively.\"","\"हजुरआमा पनि फोटोमा हुनुहुन्छ। उहाँ असी वर्षकी, तर स्वस्थ र फुर्तिली हुनुहुन्छ।\""],["– Teillä on iso ja kaunis perhe! Mei sanoo.","\"You have a big and beautiful family!\" Mei says.","\"तिम्रो परिवार ठूलो र सुन्दर छ!\" मेई भन्छिन्।"],["Ram hymyilee. Hänellä on hyvä ystävä Suomessa.","Ram smiles. He has a good friend in Finland.","राम मुस्कुराउँछन्। फिनल्यान्डमा उनको राम्रो साथी छ।"]]],
q:[["mc","Kuinka vanha Ramin äiti on?","How old is Ram's mother?",["42","52","25"],1],["mc","Mikä Ramin äiti on ammatiltaan?","What is Ram's mother's job?",["lääkäri","opettaja","myyjä"],1],["tf","Isällä on parta.","Father has a beard.",true],["mc","Montako veljeä Ramilla on?","How many brothers does Ram have?",["yksi","kaksi","ei yhtään"],1],["mc","Millainen tukka Ashalla on?","What hair does Asha have?",["pitkä ja suora","lyhyt ja kihara","musta ja pitkä"],1],["tf","Meillä on sisko.","Mei has a sister.",false],["mc","Mikä Mein lemmikki on?","What is Mei's pet?",["koira","kissa","lintu"],1],["mc","Milloin Ram soittaa äidille?","When does Ram call his mother?",["joka päivä","joka sunnuntai","joka lauantai"],1]],
open:[["Onko sinulla sisaruksia?","On. Minulla on yksi sisko ja kaksi veljeä."],["Millainen sinun äitisi on?","Hän on ahkera ja kärsivällinen. Hänellä on pitkä musta tukka."],["Onko sinulla lemmikkiä?","Ei ole. Minulla ei ole lemmikkiä."]]},

k5:{h:["Sitan päivä","Sita's day","सीताको दिन"], pre:["A normal day from 6.00 to 23.00. Look for clock times (puoli, yli, vaille) and all verb types.","बिहान ६ देखि राति ११ सम्मको दिन। घडीका शब्द खोज्नुहोस्।"],
paras:[
[["Sita herää kello kuusi. Herätyskello soi, mutta hän ei nouse heti.","Sita wakes up at six. The alarm rings, but she doesn't get up at once.","सीता छ बजे ब्युँझिन्छिन्। अलार्म बज्छ, तर उनी तुरुन्तै उठ्दिनन्।"],["Kello kymmenen yli kuusi hän nousee ja menee suihkuun.","At ten past six she gets up and goes to the shower.","छ बजेर दस मिनेटमा उनी उठ्छिन् र नुहाउन जान्छिन्।"],["Sitten hän pukeutuu ja harjaa hiukset.","Then she gets dressed and brushes her hair.","अनि उनी लुगा लगाउँछिन् र कपाल कोर्छिन्।"],["Aamupalaksi hän syö puuroa ja juo teetä maidon kanssa.","For breakfast she eats porridge and drinks tea with milk.","बिहानको खाजामा उनी दलिया खान्छिन् र दूध हालेको चिया पिउँछिन्।"]],
[["Kello puoli kahdeksan hän lähtee kotoa.","At half past seven she leaves home.","साढे सात बजे उनी घरबाट निस्कन्छिन्।"],["Hän menee junalla yliopistoon. Junassa hän kuuntelee musiikkia.","She goes to the university by train. On the train she listens to music.","उनी रेलमा विश्वविद्यालय जान्छिन्। रेलमा उनी संगीत सुन्छिन्।"],["Luento alkaa varttia yli kahdeksan.","The lecture starts at a quarter past eight.","लेक्चर सवा आठ बजे सुरु हुन्छ।"],["Kello yksitoista hän syö lounasta opiskelijaravintolassa. Lounas maksaa vain kolme euroa.","At eleven she eats lunch at the student restaurant. Lunch costs only three euros.","एघार बजे उनी विद्यार्थी क्यान्टिनमा खाजा खान्छिन्। खाजा तीन युरो मात्र पर्छ।"]],
[["Iltapäivällä hän on kirjastossa. Hän kirjoittaa esseetä ja opiskelee suomea.","In the afternoon she is at the library. She writes an essay and studies Finnish.","दिउँसो उनी पुस्तकालयमा हुन्छिन्। उनी निबन्ध लेख्छिन् र फिनिस पढ्छिन्।"],["Kello neljä hän tapaa ystävän. He juovat kahvia ja juttelevat.","At four she meets a friend. They drink coffee and chat.","चार बजे उनी साथीलाई भेट्छिन्। उनीहरू कफी पिउँछन् र गफ गर्छन्।"],["Kello viisi hän käy kaupassa. Hän ostaa leipää, maitoa ja vihanneksia.","At five she goes to the shop. She buys bread, milk and vegetables.","पाँच बजे उनी पसल जान्छिन्। उनी रोटी, दूध र तरकारी किन्छिन्।"]],
[["Kotona hän tekee ruokaa. Tänään on linssikeittoa ja riisiä.","At home she cooks. Today there is lentil soup and rice.","घरमा उनी खाना पकाउँछिन्। आज दाल र भात छ।"],["Kämppäkaveri Emma tulee kotiin kuudelta.","Her flatmate Emma comes home at six.","कोठा-साथी एमा छ बजे घर आउँछिन्।"],["He syövät yhdessä ja katsovat televisiota.","They eat together and watch television.","उनीहरू सँगै खान्छन् र टेलिभिजन हेर्छन्।"],["Kello kahdeksan Sita soittaa äidille. Nepalissa kello on silloin varttia vaille kaksitoista.","At eight Sita calls her mother. In Nepal it is then a quarter to twelve.","आठ बजे सीता आमालाई फोन गर्छिन्। त्यतिबेला नेपालमा पौने बाह्र बजेको हुन्छ।"],["Äiti on väsynyt, mutta iloinen.","Mother is tired, but happy.","आमा थाकेकी, तर खुसी हुनुहुन्छ।"]],
[["Illalla Sita tekee kotitehtävät. Hän osaa jo paljon sanoja.","In the evening Sita does her homework. She already knows a lot of words.","बेलुका सीता गृहकार्य गर्छिन्। उनलाई धेरै शब्द आइसकेको छ।"],["Kello yksitoista hän menee nukkumaan.","At eleven she goes to bed.","एघार बजे उनी सुत्न जान्छिन्।"],["Viikonloppuisin Sita nukkuu pitkään.","At weekends Sita sleeps long.","सप्ताहान्तमा सीता धेरै बेर सुत्छिन्।"],["Lauantaina hän siivoaa ja imuroi, ja sunnuntaina hän lepää.","On Saturday she cleans and vacuums, and on Sunday she rests.","शनिबार उनी सफा गर्छिन् र भ्याकुम लगाउँछिन्, अनि आइतबार आराम गर्छिन्।"]]],
q:[["mc","Mihin aikaan Sita herää?","What time does Sita wake up?",["5.00","6.00","6.10"],1],["mc","Mitä Sita syö aamupalaksi?","What does Sita eat for breakfast?",["leipää","puuroa","riisiä"],1],["mc","Milloin Sita lähtee kotoa?","When does Sita leave home?",["7.30","8.15","8.30"],0],["mc","Miten Sita menee yliopistoon?","How does Sita go to the university?",["bussilla","junalla","pyörällä"],1],["tf","Lounas maksaa kymmenen euroa.","Lunch costs ten euros.",false],["mc","Kuka on Emma?","Who is Emma?",["opettaja","kämppäkaveri","sisko"],1],["mc","Paljonko kello on Nepalissa, kun Suomessa on 20.00?","What time is it in Nepal when it is 20.00 in Finland?",["23.45","22.00","18.15"],0],["tf","Sunnuntaina Sita siivoaa.","On Sunday Sita cleans.",false]],
open:[["Mihin aikaan sinä heräät?","Herään kello seitsemän."],["Mitä sinä teet illalla?","Illalla teen ruokaa, soitan äidille ja opiskelen suomea."],["Mitä sinä teet viikonloppuna?","Viikonloppuna nukun pitkään ja siivoan."]]},

k6:{h:["Uusi koti Puistotiellä","A new home on Puistotie","पुइस्तोतिएमा नयाँ घर"], pre:["Ram moves into a new flat. Look for missä? endings: -ssa/-ssä, -lla/-llä, and words like vieressä, edessä.","राम नयाँ फ्ल्याटमा सर्छन्। -ssa, -lla र vieressä जस्ता शब्द खोज्नुहोस्।"],
paras:[
[["Ram muuttaa uuteen asuntoon. Osoite on Puistotie 5 B 12.","Ram moves to a new flat. The address is Puistotie 5 B 12.","राम नयाँ फ्ल्याटमा सर्छन्। ठेगाना पुइस्तोतिए ५ बी १२ हो।"],["Asunto on kerrostalossa, kolmannessa kerroksessa.","The flat is in a block of flats, on the third floor.","फ्ल्याट अपार्टमेन्ट भवनको तेस्रो तलामा छ।"],["Talossa on hissi, mutta Ram kävelee portaita.","The building has a lift, but Ram takes the stairs.","भवनमा लिफ्ट छ, तर राम भर्याङ चढ्छन्।"],["Asunnossa on eteinen, olohuone, makuuhuone, keittiö ja kylpyhuone. Se on kaksio.","The flat has a hall, a living room, a bedroom, a kitchen and a bathroom. It is a two-room flat.","फ्ल्याटमा ढोकाछेउको कोठा, बैठक, सुत्ने कोठा, भान्सा र बाथरुम छ। यो दुई कोठे हो।"]],
[["Olohuoneessa on sohva, pieni pöytä ja kirjahylly.","In the living room there is a sofa, a small table and a bookshelf.","बैठक कोठामा सोफा, सानो टेबल र किताब दराज छ।"],["Ikkunan edessä on iso kasvi.","In front of the window there is a big plant.","झ्यालको अगाडि ठूलो बोट छ।"],["Makuuhuoneessa on sänky ja vaatekaappi. Sängyn vieressä on lamppu.","In the bedroom there is a bed and a wardrobe. Next to the bed there is a lamp.","सुत्ने कोठामा ओछ्यान र लुगा दराज छ। ओछ्यानको छेउमा बत्ती छ।"],["Keittiössä on jääkaappi, liesi ja uuni. Kaapissa on lautasia, laseja ja mukeja.","In the kitchen there is a fridge, a stove and an oven. In the cupboard there are plates, glasses and mugs.","भान्सामा फ्रिज, चुलो र ओभन छ। दराजमा थाल, गिलास र मग छन्।"],["Kylpyhuoneessa on suihku, peili ja pesukone. Talon kellarissa on sauna.","In the bathroom there is a shower, a mirror and a washing machine. There is a sauna in the basement.","बाथरुममा सावर, ऐना र लुगा धुने मेसिन छ। भवनको तहखानामा सौना छ।"],["Ikkunasta näkyy puisto. Puistossa on puita ja penkkejä.","A park can be seen from the window. In the park there are trees and benches.","झ्यालबाट पार्क देखिन्छ। पार्कमा रूख र बेन्चहरू छन्।"]],
[["Ensimmäinen ilta uudessa kodissa on kylmä. Patteri ei toimi!","The first evening in the new home is cold. The radiator doesn't work!","नयाँ घरमा पहिलो साँझ चिसो छ। हिटरले काम गर्दैन!"],["Ram soittaa huoltomiehelle.","Ram calls the caretaker.","राम मर्मत कर्मचारीलाई फोन गर्छन्।"],["– Hei, täällä Ram Sharma, Puistotie 5 B 12. Makuuhuoneen patteri ei toimi.","\"Hi, this is Ram Sharma, Puistotie 5 B 12. The bedroom radiator doesn't work.\"","\"नमस्ते, म राम शर्मा, पुइस्तोतिए ५ बी १२ बाट। सुत्ने कोठाको हिटर चल्दैन।\""],["– Selvä. Tulen huomenna kello yhdeksän. Ole kotona!","\"OK. I'll come tomorrow at nine. Be at home!\"","\"ठीक छ। म भोलि नौ बजे आउँछु। घरमै बस्नू!\""],["Aamulla huoltomies tulee ja korjaa patterin.","In the morning the caretaker comes and repairs the radiator.","बिहान मर्मत कर्मचारी आएर हिटर बनाउँछन्।"],["– Nyt se toimii. Avaa patteri näin, älä peitä sitä.","\"Now it works. Open the radiator like this, don't cover it.\"","\"अब चल्छ। हिटर यसरी खोल, नछोप।\""]],
[["Iltapäivällä naapuri koputtaa oveen. Hän on vanha mies, Pekka.","In the afternoon a neighbour knocks on the door. He is an old man, Pekka.","दिउँसो छिमेकीले ढोका ढकढक्याउँछन्। उनी बूढा मान्छे पेक्का हुन्।"],["– Tervetuloa taloon! Roskakatos on pihalla, ja pesutupa on kellarissa.","\"Welcome to the building! The bin shelter is in the yard, and the laundry room is in the basement.\"","\"भवनमा स्वागत छ! फोहोर राख्ने ठाउँ आँगनमा र लुगा धुने कोठा तहखानामा छ।\""],["– Kiitos! Missä postilaatikot ovat?","\"Thanks! Where are the letterboxes?\"","\"धन्यवाद! पत्रपेटिकाहरू कहाँ छन्?\""],["– Ne ovat alakerrassa, hissin vieressä.","\"They are downstairs, next to the lift.\"","\"तल्लो तलामा, लिफ्टको छेउमा छन्।\""]],
[["Illalla Ram on tyytyväinen.","In the evening Ram is satisfied.","बेलुका राम सन्तुष्ट छन्।"],["Koti on pieni, mutta lämmin ja valoisa.","The home is small, but warm and bright.","घर सानो छ, तर न्यानो र उज्यालो छ।"],["Huomenna hän ostaa maton ja verhot.","Tomorrow he will buy a rug and curtains.","भोलि उनी गलैंचा र पर्दा किन्छन्।"]]],
q:[["mc","Missä kerroksessa asunto on?","Which floor is the flat on?",["toisessa","kolmannessa","viidennessä"],1],["mc","Mikä asunto on?","What kind of flat is it?",["yksiö","kaksio","kolmio"],1],["mc","Missä lamppu on?","Where is the lamp?",["ikkunan edessä","sängyn vieressä","pöydän alla"],1],["mc","Missä sauna on?","Where is the sauna?",["kylpyhuoneessa","kellarissa","pihalla"],1],["tf","Ensimmäisenä iltana asunnossa on lämmin.","On the first evening the flat is warm.",false],["mc","Milloin huoltomies tulee?","When does the caretaker come?",["illalla","aamulla kello yhdeksän","viikonloppuna"],1],["mc","Missä postilaatikot ovat?","Where are the letterboxes?",["pihalla","hissin vieressä","kellarissa"],1],["tf","Ram ostaa huomenna maton ja verhot.","Tomorrow Ram will buy a rug and curtains.",true]],
open:[["Missä sinä asut?","Asun kerrostalossa Espoossa, toisessa kerroksessa."],["Mitä sinun olohuoneessasi on?","Olohuoneessa on sohva, pöytä ja televisio."],["Kenelle soitat, jos patteri ei toimi?","Soitan huoltomiehelle."]]},

k7:{h:["Kesäloma järven rannalla","Summer holiday on the lake shore","तालको किनारमा गर्मी बिदा"], pre:["Ram plans a trip to a summer cottage. Look for transport words (junalla, autolla) and mihin? endings (-lle, -an).","राम गर्मी कुटीको यात्रा योजना बनाउँछन्। यातायातका शब्द खोज्नुहोस्।"],
paras:[
[["Heinäkuussa Ramilla on kesäloma.","In July Ram has his summer holiday.","जुलाईमा रामको गर्मी बिदा हुन्छ।"],["Mikko kutsuu hänet perheen kesämökille.","Mikko invites him to his family's summer cottage.","मिक्कोले उनलाई परिवारको गर्मी कुटीमा बोलाउँछन्।"],["Mökki on Saimaalla, Itä-Suomessa.","The cottage is at Saimaa, in eastern Finland.","कुटी पूर्वी फिनल्यान्डको साइमा तालमा छ।"],["Ram ostaa junalipun VR:n sovelluksesta. Menopaluu maksaa kuusikymmentä euroa.","Ram buys a train ticket in the VR app. A return ticket costs sixty euros.","राम VR को एपबाट रेल टिकट किन्छन्। आउने-जाने टिकट साठी युरो पर्छ।"]],
[["Juna lähtee Helsingistä kello yhdeksän, ja matka kestää neljä tuntia.","The train leaves Helsinki at nine, and the journey takes four hours.","रेल नौ बजे हेल्सिंकीबाट छुट्छ, र यात्रा चार घण्टाको हुन्छ।"],["Ramilla on ikkunapaikka vaunussa kolme.","Ram has a window seat in carriage three.","रामको डिब्बा तीनमा झ्यालछेउको सिट छ।"],["Hän katsoo ikkunasta metsiä ja järviä.","He looks at forests and lakes from the window.","उनी झ्यालबाट जंगल र तालहरू हेर्छन्।"],["Asemalla Mikko odottaa autolla. – Tervetuloa Savoon!","Mikko waits at the station by car. \"Welcome to Savo!\"","स्टेसनमा मिक्को गाडी लिएर पर्खिरहेका छन्। \"साभोमा स्वागत छ!\""]],
[["Mökki on pieni punainen talo järven rannalla.","The cottage is a small red house on the lake shore.","कुटी तालको किनारमा सानो रातो घर हो।"],["Siellä ei ole suihkua, mutta siellä on sauna, laituri ja soutuvene!","There is no shower there, but there is a sauna, a jetty and a rowing boat!","त्यहाँ सावर छैन, तर सौना, घाट र डुङ्गा छ!"],["Mikon äiti ja isä ovat jo mökillä.","Mikko's mother and father are already at the cottage.","मिक्कोका आमा र बुबा पहिले नै कुटीमा हुनुहुन्छ।"],["Isä kalastaa, ja äiti lukee kirjaa laiturilla.","Father fishes, and mother reads a book on the jetty.","बुबा माछा मार्नुहुन्छ, आमा घाटमा किताब पढ्नुहुन्छ।"]],
[["Illalla he lämmittävät saunan.","In the evening they heat the sauna.","बेलुका उनीहरू सौना तताउँछन्।"],["Saunan jälkeen he uivat järvessä. Vesi on kylmää, mutta ihanaa!","After the sauna they swim in the lake. The water is cold, but lovely!","सौनापछि उनीहरू तालमा पौडिन्छन्। पानी चिसो, तर रमाइलो छ!"],["Kesällä on yötön yö. Kello on yksitoista illalla, mutta ulkona on valoisaa.","In summer there is the nightless night. It is eleven at night, but it is light outside.","गर्मीमा रात पर्दैन। राति एघार बजेको छ, तर बाहिर उज्यालो छ।"],["He paistavat makkaraa nuotiolla ja juovat mehua.","They grill sausages on the campfire and drink juice.","उनीहरू आगोमा ससेज पोल्छन् र जुस पिउँछन्।"],["Hyttysiä on paljon! Ram tarvitsee hyttysmyrkkyä.","There are lots of mosquitoes! Ram needs mosquito repellent.","धेरै लामखुट्टे छन्! रामलाई लामखुट्टे भगाउने औषधि चाहिन्छ।"]],
[["Seuraavana päivänä he soutavat saareen ja poimivat mustikoita.","The next day they row to an island and pick blueberries.","भोलिपल्ट उनीहरू डुङ्गा चलाएर टापुमा जान्छन् र ब्लुबेरी टिप्छन्।"],["Ram ajattelee: Suomen kesä on lyhyt, mutta se on tosi kaunis.","Ram thinks: the Finnish summer is short, but it is really beautiful.","राम सोच्छन्: फिनल्यान्डको गर्मी छोटो छ, तर साँच्चै सुन्दर छ।"],["Talvella hän haluaa matkustaa Lappiin ja nähdä revontulet.","In winter he wants to travel to Lapland and see the northern lights.","जाडोमा उनी ल्यापल्यान्ड गएर उत्तरी ज्योति हेर्न चाहन्छन्।"],["Ja joulukuussa hän lentää Kathmanduun. Hän varaa jo lennon.","And in December he flies to Kathmandu. He is already booking the flight.","अनि डिसेम्बरमा उनी काठमाडौं उड्छन्। उनी अहिल्यै उडान बुक गर्दैछन्।"]]],
q:[["mc","Milloin Ramilla on kesäloma?","When is Ram's summer holiday?",["kesäkuussa","heinäkuussa","elokuussa"],1],["mc","Missä mökki on?","Where is the cottage?",["Lapissa","Saimaalla","Turussa"],1],["mc","Paljonko lippu maksaa?","How much is the ticket?",["16 €","60 €","40 €"],1],["mc","Kauanko junamatka kestää?","How long does the train journey take?",["2 tuntia","4 tuntia","9 tuntia"],1],["tf","Mökillä on suihku.","The cottage has a shower.",false],["mc","Mitä isä tekee?","What does father do?",["lukee","kalastaa","ui"],1],["mc","Mitä he poimivat saaressa?","What do they pick on the island?",["mansikoita","mustikoita","sieniä"],1],["tf","Talvella Ram haluaa matkustaa Lappiin.","In winter Ram wants to travel to Lapland.",true]],
open:[["Mihin sinä haluat matkustaa?","Haluan matkustaa Lappiin."],["Miten sinä matkustat Tampereelle?","Matkustan junalla."],["Mitä mökillä tehdään?","Mökillä saunotaan, uidaan ja kalastetaan."]]},

k8:{h:["Tupaantuliaiset","The housewarming party","गृहप्रवेश भोज"], pre:["Ram and Sita shop and cook for a party. Look for food words in the partitive (riisiä, maitoa) and dates.","राम र सीता भोजका लागि किनमेल गरी पकाउँछन्। खानाका शब्द खोज्नुहोस्।"],
paras:[
[["Ram kirjoittaa kutsun: Tervetuloa tupaantuliaisiin lauantaina 14.12. kello 18!","Ram writes an invitation: Welcome to the housewarming party on Saturday 14 December at 18!","राम निमन्त्रणा लेख्छन्: शनिबार १४ डिसेम्बर साँझ ६ बजे गृहप्रवेश भोजमा स्वागत छ!"],["Perjantaina Ram ja Sita menevät ruokakauppaan. Heillä on ostoslista.","On Friday Ram and Sita go to the grocery store. They have a shopping list.","शुक्रबार राम र सीता किराना पसल जान्छन्। उनीहरूसँग किनमेल सूची छ।"],["He ostavat riisiä, linssejä, perunoita, sipulia, valkosipulia ja inkivääriä.","They buy rice, lentils, potatoes, onion, garlic and ginger.","उनीहरू चामल, दाल, आलु, प्याज, लसुन र अदुवा किन्छन्।"],["Sita haluaa tehdä momoja. Hän tarvitsee jauhoja, jauhelihaa ja kaalia.","Sita wants to make momos. She needs flour, minced meat and cabbage.","सीता मम बनाउन चाहन्छिन्। उनलाई पीठो, किमा र बन्दा चाहिन्छ।"],["Ram ostaa myös mehua, limsaa ja kahvia. Kassalla he maksavat neljäkymmentäkahdeksan euroa.","Ram also buys juice, soft drinks and coffee. At the checkout they pay forty-eight euros.","राम जुस, सफ्ट ड्रिंक र कफी पनि किन्छन्। काउन्टरमा उनीहरू अठचालीस युरो तिर्छन्।"]],
[["Lauantaina he laittavat ruokaa koko päivän.","On Saturday they cook all day.","शनिबार उनीहरू दिनभर खाना पकाउँछन्।"],["Keittiö on täynnä hyviä tuoksuja.","The kitchen is full of good smells.","भान्सा मीठो बासनाले भरिएको छ।"],["Ram keittää dal bhatia: linssikeittoa ja riisiä.","Ram cooks dal bhat: lentil soup and rice.","राम दाल-भात पकाउँछन्।"],["Sita leikkaa sipulia ja sekoittaa mausteita.","Sita cuts onions and mixes spices.","सीता प्याज काट्छिन् र मसला मिसाउँछिन्।"]],
[["Kello kuusi ovikello soi. Ensimmäiset vieraat ovat Mei ja Anna.","At six the doorbell rings. The first guests are Mei and Anna.","छ बजे ढोकाको घण्टी बज्छ। पहिलो पाहुना मेई र आन्ना हुन्।"],["– Onnea uuteen kotiin! He antavat kukkakimpun ja suklaata.","\"Congratulations on your new home!\" They give a bunch of flowers and chocolate.","\"नयाँ घरको बधाई!\" उनीहरू फूलको गुच्छा र चकलेट दिन्छन्।"],["Sitten tulee Mikko. Hänellä on lahjana leipää ja suolaa.","Then Mikko comes. He has bread and salt as a gift.","त्यसपछि मिक्को आउँछन्। उनी उपहारमा रोटी र नुन ल्याउँछन्।"],["– Leipää ja suolaa uuteen kotiin – se on suomalainen perinne, Mikko sanoo.","\"Bread and salt for a new home – it's a Finnish tradition,\" Mikko says.","\"नयाँ घरका लागि रोटी र नुन – यो फिनिस परम्परा हो,\" मिक्को भन्छन्।"],["Naapuri Pekka tuo pullaa.","Neighbour Pekka brings sweet buns.","छिमेकी पेक्का मीठो रोटी ल्याउँछन्।"]],
[["Pöydällä on riisiä, dalia, momoja, salaattia ja jogurttia.","On the table there is rice, dal, momos, salad and yoghurt.","टेबलमा भात, दाल, मम, सलाद र दही छ।"],["Pöydän keskellä on kynttilä.","In the middle of the table there is a candle.","टेबलको बीचमा मैनबत्ती छ।"],["– Ottakaa, olkaa hyvä! Ram sanoo.","\"Help yourselves, please!\" Ram says.","\"लिनुहोस्!\" राम भन्छन्।"],["– Mmm, tämä on herkullista! Onko tämä tulista? Mikko kysyy.","\"Mmm, this is delicious! Is this spicy?\" Mikko asks.","\"म्म, यो मीठो छ! यो पिरो छ?\" मिक्को सोध्छन्।"],["– Vähän! Juo vettä tai maitoa, Sita nauraa.","\"A little! Drink water or milk,\" Sita laughs.","\"अलिकति! पानी वा दूध पिउनुहोस्,\" सीता हाँस्छिन्।"]],
[["Jälkiruoaksi on täytekakkua ja kahvia. Mei on tehnyt kakun.","For dessert there is layer cake and coffee. Mei has made the cake.","खानापछि क्रिम केक र कफी छ। मेईले केक बनाएकी छिन्।"],["Kakun päällä on mansikoita.","There are strawberries on top of the cake.","केकमाथि स्ट्रबेरी छन्।"],["Ilta on hauska. Vieraat lähtevät kello yksitoista.","The evening is fun. The guests leave at eleven.","साँझ रमाइलो हुन्छ। पाहुनाहरू एघार बजे जान्छन्।"],["– Kiitos illasta! – Kiitos, kun tulitte!","\"Thanks for the evening!\" – \"Thanks for coming!\"","\"साँझका लागि धन्यवाद!\" – \"आउनुभएकोमा धन्यवाद!\""],["Ram on onnellinen. Hänellä on nyt koti ja ystäviä Suomessa.","Ram is happy. He now has a home and friends in Finland.","राम खुसी छन्। अब फिनल्यान्डमा उनको घर र साथीहरू छन्।"]]],
q:[["mc","Milloin juhlat ovat?","When is the party?",["perjantaina 13.12.","lauantaina 14.12.","sunnuntaina 15.12."],1],["mc","Mitä Sita haluaa tehdä?","What does Sita want to make?",["pizzaa","momoja","kakkua"],1],["mc","Paljonko ostokset maksavat?","How much does the shopping cost?",["18 €","48 €","84 €"],1],["mc","Keitä ovat ensimmäiset vieraat?","Who are the first guests?",["Mikko ja Pekka","Mei ja Anna","Sita ja Mikko"],1],["mc","Mitä Mikko tuo?","What does Mikko bring?",["kukkia","leipää ja suolaa","pullaa"],1],["tf","Ruoka on vähän tulista.","The food is a bit spicy.",true],["mc","Kuka tekee kakun?","Who makes the cake?",["Sita","Mei","Anna"],1],["tf","Vieraat lähtevät kello yhdeksän.","The guests leave at nine.",false]],
open:[["Mitä sinä ostat kaupasta?","Ostan riisiä, maitoa, leipää ja vihanneksia."],["Mikä on sinun lempiruokasi?","Minun lempiruokani on dal bhat."],["Milloin sinun syntymäpäiväsi on?","Syntymäpäiväni on toukokuun kahdeksas päivä."]]},

k9:{h:["Ram saa työn","Ram gets a job","रामले काम पाउँछन्"], pre:["A job search, an interview and a first shift. Look for koska (because), että (that), kun (when) and jos (if).","काम खोजी, अन्तर्वार्ता र पहिलो सिफ्ट। koska, että, kun, jos खोज्नुहोस्।"],
paras:[
[["Ram etsii osa-aikatyötä, koska opiskelu on kallista.","Ram is looking for a part-time job, because studying is expensive.","राम आंशिक काम खोज्दैछन्, किनभने पढाइ महँगो छ।"],["Hän lukee työpaikkailmoituksia netistä.","He reads job ads on the internet.","उनी इन्टरनेटमा कामको विज्ञापन पढ्छन्।"],["Kahvila Kanerva etsii myyjää.","Café Kanerva is looking for a salesperson.","क्याफे कानेर्भालाई बिक्रेता चाहिएको छ।"],["Ram kirjoittaa hakemuksen ja lähettää CV:n sähköpostilla.","Ram writes an application and sends his CV by email.","राम आवेदन लेख्छन् र इमेलबाट बायोडाटा पठाउँछन्।"]],
[["Kaksi päivää myöhemmin puhelin soi.","Two days later the phone rings.","दुई दिनपछि फोन बज्छ।"],["– Hei, täällä Laura Kahvila Kanervasta. Tuletko työhaastatteluun torstaina kello kymmenen?","\"Hi, this is Laura from Café Kanerva. Will you come to an interview on Thursday at ten?\"","\"नमस्ते, म क्याफे कानेर्भाबाट लौरा। बिहीबार दस बजे अन्तर्वार्तामा आउँछौ?\""],["– Tulen mielelläni!","\"I'd be glad to!\"","\"खुसीसाथ आउँछु!\""],["Torstaina Ram pukeutuu siististi. Hän on vähän jännittynyt.","On Thursday Ram dresses neatly. He is a bit nervous.","बिहीबार राम सफा लुगा लगाउँछन्। उनी अलि नर्भस छन्।"]],
[["– Miksi haluat työtä kahvilassa? Laura kysyy.","\"Why do you want a job in a café?\" Laura asks.","\"किन क्याफेमा काम गर्न चाहन्छौ?\" लौरा सोध्छिन्।"],["– Koska pidän asiakaspalvelusta ja haluan puhua suomea joka päivä.","\"Because I like customer service and I want to speak Finnish every day.\"","\"किनभने मलाई ग्राहक सेवा मन पर्छ र हरेक दिन फिनिस बोल्न चाहन्छु।\""],["– Puhutko englantia? – Puhun, ja puhun myös nepalia ja hindiä.","\"Do you speak English?\" – \"I do, and I also speak Nepali and Hindi.\"","\"अंग्रेजी बोल्छौ?\" – \"बोल्छु, नेपाली र हिन्दी पनि बोल्छु।\""],["– Milloin sinulla on aikaa? – Maanantaina, keskiviikkona ja lauantaina.","\"When are you free?\" – \"On Monday, Wednesday and Saturday.\"","\"तिमीलाई कहिले फुर्सद हुन्छ?\" – \"सोमबार, बुधबार र शनिबार।\""],["Laura sanoo, että työ alkaa ensi maanantaina. Ram saa työn!","Laura says that the job starts next Monday. Ram gets the job!","लौरा भन्छिन्, काम अर्को सोमबारदेखि सुरु हुन्छ। रामले काम पाउँछन्!"]],
[["Työvuoro alkaa kello seitsemän aamulla.","The shift starts at seven in the morning.","सिफ्ट बिहान सात बजे सुरु हुन्छ।"],["Ram keittää kahvia, paistaa pullia ja palvelee asiakkaita.","Ram makes coffee, bakes buns and serves customers.","राम कफी बनाउँछन्, मीठो रोटी पकाउँछन् र ग्राहकको सेवा गर्छन्।"],["Työkaveri Alex on Brasiliasta. Hän on ystävällinen ja auttaa Ramia.","His colleague Alex is from Brazil. He is friendly and helps Ram.","सहकर्मी एलेक्स ब्राजिलबाट हुन्। उनी मिलनसार छन् र रामलाई सहयोग गर्छन्।"],["– Jos kassa ei toimi, soita Lauralle, Alex neuvoo.","\"If the till doesn't work, call Laura,\" Alex advises.","\"यदि क्यास मेसिन चलेन भने लौरालाई फोन गर,\" एलेक्स सल्लाह दिन्छन्।"],["Lounastauko on puoli tuntia. Ram syö voileivän ja juo kahvia.","The lunch break is half an hour. Ram eats a sandwich and drinks coffee.","खाजा समय आधा घण्टा हो। राम स्यान्डविच खान्छन् र कफी पिउँछन्।"]],
[["Palkka on kaksitoista euroa tunnissa.","The wage is twelve euros an hour.","तलब घण्टाको बाह्र युरो हो।"],["Ram tarvitsee verokortin, joten hän tilaa sen netistä.","Ram needs a tax card, so he orders it online.","रामलाई कर कार्ड चाहिन्छ, त्यसैले उनी इन्टरनेटबाट मगाउँछन्।"],["Kun työpäivä loppuu kello yksi, Ram menee luennolle.","When the working day ends at one, Ram goes to a lecture.","एक बजे काम सकिएपछि राम लेक्चरमा जान्छन्।"],["Illalla hän on väsynyt, mutta tyytyväinen. Hän oppii töissä paljon uusia sanoja.","In the evening he is tired but satisfied. He learns lots of new words at work.","बेलुका उनी थाकेका, तर सन्तुष्ट हुन्छन्। काममा उनी धेरै नयाँ शब्द सिक्छन्।"]],
[["Yhtenä päivänä Ram on sairas. Hänellä on kuumetta.","One day Ram is ill. He has a fever.","एक दिन राम बिरामी छन्। उनलाई ज्वरो आएको छ।"],["Hän soittaa Lauralle: – Olen sairas, en pääse töihin tänään.","He calls Laura: \"I'm ill, I can't come to work today.\"","उनी लौरालाई फोन गर्छन्: \"म बिरामी छु, आज काममा आउन सक्दिनँ।\""],["– Selvä. Lepää ja parane pian!","\"OK. Rest and get well soon!\"","\"ठीक छ। आराम गर र छिट्टै निको होऊ!\""]]],
q:[["mc","Miksi Ram etsii työtä?","Why is Ram looking for a job?",["koska hänellä on tylsää","koska opiskelu on kallista","koska Mikko sanoo niin"],1],["mc","Mistä Ram lukee ilmoituksia?","Where does Ram read the ads?",["lehdestä","netistä","kirjastosta"],1],["mc","Milloin haastattelu on?","When is the interview?",["tiistaina","torstaina","lauantaina"],1],["tf","Ram on haastattelussa vähän jännittynyt.","Ram is a bit nervous at the interview.",true],["mc","Milloin Ramilla on aikaa?","When is Ram free?",["ma, ke, la","ti, to, pe","joka päivä"],0],["mc","Mistä Alex on kotoisin?","Where is Alex from?",["Brasiliasta","Puolasta","Kiinasta"],0],["mc","Paljonko palkka on?","How much is the wage?",["10 €/h","12 €/h","20 €/h"],1],["tf","Kun Ram on sairas, hän menee töihin.","When Ram is ill, he goes to work.",false]],
open:[["Mitä sinä teet työksesi?","Olen opiskelija. Teen myös osa-aikatyötä kahvilassa."],["Miksi sinä opiskelet suomea?","Koska asun Suomessa ja haluan tehdä töitä täällä."],["Mitä sanot, kun olet sairas?","Olen sairas, en pääse töihin tänään."]]},

k10:{h:["Ensimmäinen joulu Suomessa","My first Christmas in Finland","फिनल्यान्डमा पहिलो क्रिसमस"], pre:["Written after Christmas, in the past tense. Look for -i- forms: oli, söivät, matkusti, sai.","क्रिसमसपछि भूतकालमा लेखिएको। oli, söivät, matkusti जस्ता रूप खोज्नुहोस्।"],
paras:[
[["Joulu oli Ramille uusi kokemus.","Christmas was a new experience for Ram.","क्रिसमस रामका लागि नयाँ अनुभव थियो।"],["Joulukuussa kaupungissa oli paljon valoja.","In December there were lots of lights in the city.","डिसेम्बरमा शहरमा धेरै बत्ती थिए।"],["Kauppakeskuksessa oli iso joulukuusi.","There was a big Christmas tree in the shopping centre.","सपिङ सेन्टरमा ठूलो क्रिसमस रूख थियो।"],["Mikon perhe kutsui Ramin jouluksi Turkuun.","Mikko's family invited Ram to Turku for Christmas.","मिक्कोको परिवारले रामलाई क्रिसमसमा टुर्कु बोलायो।"]],
[["Ram matkusti Turkuun junalla jouluaattona.","Ram travelled to Turku by train on Christmas Eve.","राम क्रिसमसको अघिल्लो दिन रेलमा टुर्कु गए।"],["Juna oli täynnä ihmisiä ja lahjoja.","The train was full of people and presents.","रेल मानिस र उपहारले भरिएको थियो।"],["Mikon äiti avasi oven. – Hyvää joulua! Tervetuloa!","Mikko's mother opened the door. \"Merry Christmas! Welcome!\"","मिक्कोकी आमाले ढोका खोल्नुभयो। \"क्रिसमसको शुभकामना! स्वागत छ!\""],["Ensin he söivät riisipuuroa. Ram löysi puurosta mantelin!","First they ate rice porridge. Ram found an almond in the porridge!","पहिले उनीहरूले खीर खाए। रामले खीरमा बदाम भेटे!"],["– Se tarkoittaa onnea, Mikon mummo sanoi.","\"It means luck,\" Mikko's grandmother said.","\"यसको अर्थ भाग्य हो,\" मिक्कोकी हजुरआमाले भन्नुभयो।"]],
[["Kello kaksitoista he kuuntelivat radiosta joulurauhan julistuksen.","At twelve they listened to the Declaration of Christmas Peace on the radio.","बाह्र बजे उनीहरूले रेडियोमा क्रिसमस शान्तिको घोषणा सुने।"],["Iltapäivällä he kävivät saunassa.","In the afternoon they went to the sauna.","दिउँसो उनीहरू सौना गए।"],["Sitten he söivät jouluruokaa: kinkkua, lohta ja laatikoita.","Then they ate Christmas food: ham, salmon and casseroles.","अनि उनीहरूले क्रिसमसको खाना खाए: ह्याम, साल्मन र विभिन्न परिकार।"],["Ram ei syönyt kinkkua, mutta hän söi paljon lohta ja porkkanalaatikkoa.","Ram didn't eat ham, but he ate a lot of salmon and carrot casserole.","रामले ह्याम खाएनन्, तर धेरै साल्मन र गाजरको परिकार खाए।"]],
[["Illalla joulupukki tuli! – Onko täällä kilttejä lapsia? hän kysyi.","In the evening Father Christmas came! \"Are there any good children here?\" he asked.","बेलुका सान्ता क्लज आए! \"यहाँ असल बच्चाहरू छन्?\" उनले सोधे।"],["Mikon pikkuveli nauroi.","Mikko's little brother laughed.","मिक्कोको सानो भाइ हाँस्यो।"],["Ram sai lahjaksi villasukat. Mikon mummo kutoi ne.","Ram got wool socks as a present. Mikko's grandmother knitted them.","रामले उपहारमा ऊनी मोजा पाए। मिक्कोकी हजुरआमाले बुन्नुभएको थियो।"],["Ram antoi perheelle nepalilaista teetä ja kauniin huivin.","Ram gave the family Nepali tea and a beautiful scarf.","रामले परिवारलाई नेपाली चिया र सुन्दर सल दिए।"]],
[["Joulupäivänä oli hiljaista. He kävelivät lumisessa metsässä ja joivat glögiä.","On Christmas Day it was quiet. They walked in the snowy forest and drank glögi.","क्रिसमसको दिन शान्त थियो। उनीहरू हिउँ परेको जंगलमा हिँडे र ग्लोगी पिए।"],["Ram ajatteli kotia. Nepalissa dashain ja tihar ovat isoja juhlia.","Ram thought about home. In Nepal, Dashain and Tihar are big festivals.","रामले घरको सम्झना गरे। नेपालमा दशैं र तिहार ठूला चाड हुन्।"],["Hän soitti äidille ja kertoi suomalaisesta joulusta.","He called his mother and told her about the Finnish Christmas.","उनले आमालाई फोन गरे र फिनिस क्रिसमसबारे बताए।"],["– Oliko kylmä? äiti kysyi. – Oli, kymmenen astetta pakkasta! Mutta talossa oli lämmin.","\"Was it cold?\" mother asked. \"Yes, ten degrees below zero! But it was warm in the house.\"","\"चिसो थियो?\" आमाले सोध्नुभयो। \"थियो, माइनस दस डिग्री! तर घरभित्र न्यानो थियो।\""]],
[["Uutenavuotena Ram oli Helsingissä. He katsoivat ilotulitusta.","On New Year's Eve Ram was in Helsinki. They watched the fireworks.","नयाँ वर्षको राति राम हेल्सिंकीमा थिए। उनीहरूले आतिशबाजी हेरे।"],["Vuosi oli Ramille tärkeä.","The year was important for Ram.","यो वर्ष रामका लागि महत्त्वपूर्ण थियो।"],["Hän muutti Suomeen, aloitti opiskelun ja oppi paljon suomea.","He moved to Finland, started his studies and learned a lot of Finnish.","उनी फिनल्यान्ड सरे, पढाइ सुरु गरे र धेरै फिनिस सिके।"],["Hyvää uutta vuotta!","Happy New Year!","नयाँ वर्षको शुभकामना!"]]],
q:[["mc","Missä Ram oli jouluna?","Where was Ram at Christmas?",["Helsingissä","Turussa","Nepalissa"],1],["mc","Miten Ram matkusti?","How did Ram travel?",["bussilla","junalla","autolla"],1],["mc","Mitä Ram löysi puurosta?","What did Ram find in the porridge?",["kolikon","mantelin","rusinan"],1],["tf","Ram söi paljon kinkkua.","Ram ate a lot of ham.",false],["mc","Mitä Ram sai lahjaksi?","What did Ram get as a present?",["kirjan","villasukat","huivin"],1],["mc","Kuka kutoi sukat?","Who knitted the socks?",["Mikon äiti","Mikon mummo","Mikon sisko"],1],["mc","Paljonko pakkasta oli?","How many degrees below zero was it?",["5","10","20"],1],["tf","Uutenavuotena Ram oli Turussa.","On New Year's Eve Ram was in Turku.",false]],
open:[["Mitä sinä teit jouluna?","Jouluna olin ystävän luona. Söimme ja saunoimme."],["Mitä sinä söit eilen?","Eilen söin riisiä ja dalia."],["Mikä on Nepalin suurin juhla?","Dashain on Nepalin suurin juhla."]]}
};
